import torch, re, random
reset()

def get_int(s):
    m = re.search(r'-?\d+', s)
    return int(m.group()) if m else None

plus_ids, minus_ids, star_ids, eq_ids = [], [], [], []
for i in range(len(tok)):
    try:
        s = tok.decode([i])
    except Exception:
        continue
    t = s.strip()
    if t in ('+', '＋'): plus_ids.append(i)
    elif t in ('-', '−', '－'): minus_ids.append(i)
    elif t in ('*', '×', '＊'): star_ids.append(i)
    elif t == '=': eq_ids.append(i)
print("plus", plus_ids, "minus", minus_ids, "star", star_ids, "eq", eq_ids[:3])

rng = random.Random(42)
add_pairs = [(rng.randint(10, 99), rng.randint(10, 99)) for _ in range(10)]
sub_pairs = [(rng.randint(50, 99), rng.randint(10, 49)) for _ in range(5)]
add_qs = [f"What is {a} + {b}?" for a, b in add_pairs]
sub_qs = [f"What is {a} - {b}?" for a, b in sub_pairs]
examples = [("What is 2 + 3?", "5"), ("What is 4 + 5?", "9"), ("What is 12 + 7?", "19")]

def measure(label):
    add_ans = ask(add_qs)
    add_ex_ans = ask(add_qs, examples=examples)
    sub_ans = ask(sub_qs)
    add_ok = sum(get_int(x) == a+b for x, (a,b) in zip(add_ans, add_pairs)) / len(add_pairs)
    add_ex_ok = sum(get_int(x) == a+b for x, (a,b) in zip(add_ex_ans, add_pairs)) / len(add_pairs)
    sub_ok = sum(get_int(x) == a-b for x, (a,b) in zip(sub_ans, sub_pairs)) / len(sub_pairs)
    print(f"{label}: add {add_ok:.2f} add_ex {add_ex_ok:.2f} sub {sub_ok:.2f}")
    print("  add:", add_ans)
    print("  add_ex:", add_ex_ans)
    return add_ok, add_ex_ok, sub_ok

